    /// td's `to_string(const BaseObject&)` for the dynamic object.
    pub fn to_debug_string(&self) -> String {
        let mut out = String::new();
        let mut storer = TlStorerToString { out: &mut out, shift: 0 };
        self.store_debug(&mut storer, "");
        out
    }

