#[cfg(test)]
#[test]
#[allow(non_snake_case)]
fn __rt_AccentColor() {
    samples::__stack(move || {
        let v = samples::s_AccentColor(3);
        let mut out = Vec::new();
        v.store_boxed(&mut out);
        let w = AccentColor::parse(&out).expect("AccentColor parse");
        assert_eq!(v, w);
        let mut out = Vec::new();
        v.store(&mut out);
        let w = AccentColor::parse_bare(&out).expect("AccentColor bare parse");
        assert_eq!(v, w);
        let j = v.to_json();
        let w = AccentColor::from_json(&j).expect("AccentColor json parse");
        assert_eq!(v, w);
    });
}

